parameters.pythonCode:
grouped_data = {}

# 1. Group the data efficiently in a single pass
for item in _input.all():
    data = item.to_py()["json"]
    construct_id = data.get("construct")

    if not construct_id:
        continue

    grouped_data.setdefault(construct_id, [])

    for variation in data.get("variations", []):
        desc = variation.get("variation_description", "")

        evidence_map = variation.get("reference_audit", {}).get("evidence_map", [])
        docs = [ev.get("document_id", "") for ev in evidence_map]

        evidence_str = ", ".join(docs)

        # Added a space before the parenthesis for slightly cleaner formatting
        texto = f"{desc} ({evidence_str})" 

        grouped_data[construct_id].append(texto)

# 2. Convert the grouped dictionary into a list of dicts for n8n
output = [
    {
        "id": construct, 
        "evidences": evidences_list
    } 
    for construct, evidences_list in grouped_data.items()
]

return output

